package factory.fun;
import android.app.Activity;
import android.os.Bundle;
import android.content.SharedPreferences;
import android.content.Context;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import android.text.InputType;
import java.util.*;
public final class MainActivity extends Activity {


 private final int accent=0xff7c3aed,ink=0xff172337;
 private android.graphics.drawable.GradientDrawable shape(int color,int radius){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 private LinearLayout.LayoutParams spaced(int height,int top,int bottom){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,height);p.setMargins(0,dp(top),0,dp(bottom));return p;}
 private void hero(View v,int height){v.setBackground(shape(0xffedf2f8,20));v.setClipToOutline(true);root.addView(v,spaced(dp(height),8,12));}
 private void buzz(View v){v.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);}

 private LinearLayout root;private ScrollView scroll;private TextView status;private SharedPreferences prefs;
 private String t(String en,String ko,String ja){String l=getResources().getConfiguration().getLocales().get(0).getLanguage();return "ko".equals(l)?ko:"ja".equals(l)?ja:en;}
 private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private void setup(String intro){prefs=getSharedPreferences("local",MODE_PRIVATE);scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(0xfff6f8fc);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(22),dp(18),dp(22),dp(30));scroll.addView(root);setContentView(scroll);scroll.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets a=i.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(a.left,a.top,a.right,a.bottom);return i;});TextView title=label(getString(R.string.app_name));title.setTextSize(34);title.setTextColor(accent);title.setTypeface(null,Typeface.BOLD);label(intro);status=label(t("Ready","준비 완료","準備完了"));status.setTextColor(accent);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);}
 private TextView label(String s){TextView v=new TextView(this);v.setText(s);v.setTextSize(16);v.setTextColor(ink);v.setPadding(0,dp(6),0,dp(6));root.addView(v);return v;}
 private Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setMinHeight(dp(48));b.setTextColor(Color.WHITE);b.setTextSize(16);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(accent));b.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x44ffffff),shape(accent,16),null));b.setOnClickListener(v->{buzz(v);action.run();});root.addView(b,spaced(dp(52),5,5));return b;}
 private EditText edit(String name,String value){label(name);EditText e=new EditText(this);e.setContentDescription(name);e.setText(value);e.setTextColor(ink);e.setPadding(dp(14),dp(12),dp(14),dp(12));e.setBackground(shape(Color.WHITE,14));root.addView(e,spaced(-2,4,8));return e;}
 private Spinner options(String title,String... items){label(title);Spinner s=new Spinner(this);s.setContentDescription(title);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,items));s.setBackgroundTintList(android.content.res.ColorStateList.valueOf(accent));root.addView(s,spaced(dp(48),4,8));return s;}
 private void change(Spinner s,Runnable r){s.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){r.run();}public void onNothingSelected(android.widget.AdapterView<?> p){}});}

 private final Random random=new Random();private TextView result;private EditText choices;
 @Override public void onCreate(Bundle state){super.onCreate(state);setup(t("Choose, roll or play with friends. No accounts or network.","친구와 함께 선택, 주사위, 게임을 즐기세요.","友達と選択・サイコロ・ゲームを楽しもう。"));wheel=new Wheel(this);wheel.setContentDescription(t("Spinning decision wheel","회전 선택 룰렛","ルーレット"));hero(wheel,275);choices=edit(t("Options, one per line (2–30)","선택지 (한 줄에 하나, 2~30개)","候補（1行ずつ、2〜30個）"),t("Pizza\nChicken\nPasta","피자\n치킨\n파스타","ピザ\nチキン\nパスタ"));choices.setMinLines(3);choices.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(2000)});result=label("🎲");result.setTextSize(30);result.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);button(t("Spin the wheel","룰렛 돌리기","ルーレットを回す"),this::spinWheel);button(t("Coin toss","동전 던지기","コイントス"),()->result.setText(random.nextBoolean()?t("Heads","앞면","表"):t("Tails","뒷면","裏")));button(t("Roll two dice","주사위 두 개","サイコロ2個"),()->{int a=1+random.nextInt(6),b=1+random.nextInt(6);result.setText("🎲 "+a+" + "+b+" = "+(a+b));});button(t("Conversation card","대화 카드","会話カード"),()->{String[] cards={t("What is your dream holiday?","꿈꾸는 여행지는?","夢の旅行先は？"),t("Which food would you eat every day?","매일 먹고 싶은 음식은?","毎日食べたい料理は？"),t("Name a skill you want to learn.","배우고 싶은 기술은?","学びたいことは？"),t("What made you laugh recently?","최근 가장 웃겼던 일은?","最近笑ったことは？"),t("Invent a funny superhero name.","재미있는 영웅 이름을 지어 봐요.","面白いヒーローの名前を考えよう。")};result.setText(cards[random.nextInt(cards.length)]);});button(t("Family challenge","가족 미션","家族チャレンジ"),()->{String[] cards={t("Draw a cat in 20 seconds.","20초 동안 고양이를 그려요.","20秒で猫を描こう。"),t("Name five fruits.","과일 이름 다섯 개를 말해요.","果物を5つ言おう。"),t("Tell a kind joke.","기분 좋은 농담을 해요.","優しい冗談を言おう。")};result.setText(cards[random.nextInt(cards.length)]);});}

 private Wheel wheel;private android.animation.ValueAnimator spin;
 private class Wheel extends View{Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);float angle;String[] labels={"1","2","3"};Wheel(Context c){super(c);}protected void onDraw(Canvas c){float x=getWidth()/2f,y=getHeight()/2f,r=Math.min(x,y)-dp(14);if(r<=0)return;c.drawColor(0xfff3efff);int[] colors={0xff7c3aed,0xff0891b2,0xffdb2777,0xffea580c,0xff059669};float arc=360f/labels.length;RectF box=new RectF(x-r,y-r,x+r,y+r);for(int i=0;i<labels.length;i++){float a=angle+i*arc;p.setColor(colors[i%colors.length]);c.drawArc(box,a,arc,true,p);p.setColor(Color.WHITE);p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextSize(dp(labels.length>10?10:14));c.save();c.rotate(a+arc/2,x,y);String s=labels[i];if(s.length()>12)s=s.substring(0,11)+"…";float available=r*.68f;if(p.measureText(s)>available)p.setTextSize(p.getTextSize()*available/p.measureText(s));c.drawText(s,x+r*.22f,y+dp(4),p);c.restore();}p.setColor(0xff172337);c.drawCircle(x,y,dp(10),p);Path arrow=new Path();arrow.moveTo(x,y-r+dp(19));arrow.lineTo(x-dp(12),y-r-dp(5));arrow.lineTo(x+dp(12),y-r-dp(5));arrow.close();c.drawPath(arrow,p);}}
 private void spinWheel(){try{String[] a=Rules.choices(choices.getText().toString());if(spin!=null&&spin.isRunning())return;wheel.labels=a;int selected=random.nextInt(a.length);float target=270f-(selected+.5f)*360f/a.length;float end=wheel.angle+1080f+((target-wheel.angle)%360+360)%360;spin=android.animation.ValueAnimator.ofFloat(wheel.angle,end);spin.setDuration(1600);spin.setInterpolator(new android.view.animation.DecelerateInterpolator());spin.addUpdateListener(v->{wheel.angle=(Float)v.getAnimatedValue();wheel.invalidate();});spin.addListener(new android.animation.AnimatorListenerAdapter(){@Override public void onAnimationEnd(android.animation.Animator a1){if(!isFinishing()){result.setText("🎯 "+a[selected]);buzz(wheel);}}});spin.start();}catch(IllegalArgumentException e){status.setText(t("Enter 2–30 different options","서로 다른 선택지를 2~30개 입력하세요","異なる候補を2〜30個入力"));}}
 @Override protected void onDestroy(){if(spin!=null)spin.cancel();super.onDestroy();}

}
